DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_reviewer INT;
BEGIN
  FOR rec IN SELECT * FROM review_events ORDER BY event_id LOOP
    SELECT status, reviewer_id INTO cur_status, cur_reviewer FROM code_reviews WHERE code_id = rec.code_id;
    IF rec.event_type = 1 AND cur_status = 'pending' THEN
      UPDATE code_reviews SET status = 'under_review', reviewer_id = rec.clinician_id WHERE code_id = rec.code_id;
    ELSIF rec.event_type = 2 AND cur_status = 'under_review' AND cur_reviewer = rec.clinician_id THEN
      UPDATE code_reviews SET status = 'approved' WHERE code_id = rec.code_id;
    ELSIF rec.event_type = 3 AND cur_status = 'under_review' AND cur_reviewer = rec.clinician_id THEN
      UPDATE code_reviews SET status = 'denied' WHERE code_id = rec.code_id;
    ELSIF rec.event_type = 4 AND cur_status = 'under_review' THEN
      UPDATE code_reviews SET reviewer_id = rec.new_reviewer_id WHERE code_id = rec.code_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM code_reviews ORDER BY code_id;
